excerpts.text:
& $NpmCmd test
  if ($LASTEXITCODE -ne 0) { throw 'Full tests failed' }
  & $NpmCmd run check
  if ($LASTEXITCODE -ne 0) { throw 'Package checks failed' }
  & $NpmCmd run smoke

& $Npm 'test'
  if ($LASTEXITCODE -ne 0) { throw 'npm test failed; preserve outputs and investigate effects.' }
  & $Npm 'run' 'check'
